"""Decode the internal ``trk`` telemetry wire format.

Each record has a one-byte type, a little-endian uint16 payload length,
then the payload and a little-endian CRC32. CRC32 covers the header and
payload with seed 0x9c2f41b7. Payload integers are big-endian.

Samples (type 2) contain uint32 minutes since 2000-01-02 UTC, a uint24
value in thousandths, and a flag byte. Batches (type 7) contain a uint24
count, uint16 values in hundredths, and a flag byte.
"""

from datetime import datetime, timedelta, timezone
import zlib


_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_CRC_SEED = 0x9C2F41B7
_FLAG_NAMES = ("low_battery", "recal", "stale")


def decode_records(data: bytes) -> list[dict]:
    """Return decoded records, rejecting incomplete or corrupt frames."""
    records = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError(f"truncated record header at offset {offset}")
        kind = data[offset]
        length = int.from_bytes(data[offset + 1:offset + 3], "little")
        payload_end = offset + 3 + length
        end = payload_end + 4
        if end > len(data):
            raise ValueError(f"truncated record at offset {offset}")

        checksum = int.from_bytes(data[payload_end:end], "little")
        if zlib.crc32(data[offset:payload_end], _CRC_SEED) != checksum:
            raise ValueError(f"checksum mismatch at offset {offset}")
        payload = data[offset + 3:payload_end]

        if kind == 2:
            if length != 8:
                raise ValueError("invalid sample payload length")
            minutes = int.from_bytes(payload[:4], "big")
            record = {
                "type": "sample",
                "ts": (_EPOCH + timedelta(minutes=minutes)).strftime(
                    "%Y-%m-%dT%H:%M:%SZ"
                ),
                "value": int.from_bytes(payload[4:7], "big") / 1000,
            }
        elif kind == 7:
            if length < 4:
                raise ValueError("invalid batch payload length")
            count = int.from_bytes(payload[:3], "big")
            if length != 4 + 2 * count:
                raise ValueError("invalid batch payload length")
            record = {
                "type": "batch",
                "values": [
                    int.from_bytes(payload[i:i + 2], "big") / 100
                    for i in range(3, 3 + 2 * count, 2)
                ],
            }
        else:
            raise ValueError(f"unknown record type {kind}")

        record["flags"] = [
            name for bit, name in enumerate(_FLAG_NAMES)
            if payload[-1] & (1 << bit)
        ]
        records.append(record)
        offset = end
    return records
PY
